function findGCD(nums) {
  let smallest = nums[0];
  let largest = nums[0];
  for (const num of nums) {
    smallest = Math.min(smallest, num);
    largest = Math.max(largest, num);
  }
  let a = largest;
  let b = smallest;
  while (b !== 0) {
    const remainder = a % b;
    a = b;
    b = remainder;
  }
  return a;
}

