function findGCD(nums) {
  const sorted = [...nums].sort((x, y) => x - y);
  const low = sorted[0];
  const high = sorted[sorted.length - 1];
  for (let d = low; d >= 1; d--) if (low % d === 0 && high % d === 0) return d;
  return 1;
}

