function generate(rand, size) {
  const length = size === 'large' ? 1000 : 2 + Math.floor(rand() * 7);
  const limit = size === 'large' ? 1000 : 60;
  // Pick a common factor first so that answers other than 1 are frequent.
  const factor = 1 + Math.floor(rand() * (rand() < 0.5 ? 10 : limit / 2));
  const steps = Math.floor(limit / factor);
  let low = factor * (1 + Math.floor(rand() * steps));
  let high = factor * (1 + Math.floor(rand() * steps));
  if (low > high) [low, high] = [high, low];
  const nums = [low, high];
  while (nums.length < length) nums.push(low + Math.floor(rand() * (high - low + 1)));
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
